const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(data[0]);

const ones = [];
for (let i = 0; i < n; i++) {
  if (Number(data[i + 1]) === 1) {
    ones.push(i + 1);
  }
}

let answer = 0;

for (let i = 0; i < ones.length; i++) {
  const pos = ones[i];
  const prev = i === 0 ? 0 : ones[i - 1];
  const next = i === ones.length - 1 ? n + 1 : ones[i + 1];

  answer += (pos - prev) * (next - pos);
}

console.log(answer);
